-- Übungskatalog aus free-exercise-db (gemeinfrei). Erzeugt von tools/build-seed.mjs.
-- 200 Übungen, Teil 1 von 4. Deutsche Namen sind maschinell erzeugt und dürfen angepasst werden.
--
-- Das Skript ist wiederholbar: bereits vorhandene Katalogübungen (source + source_id)
-- werden aktualisiert (Namen, Muskelgruppen, Gerät, englische Anleitung). Ihre IDs bleiben
-- gleich, Pläne und Trainings bleiben also verknüpft. Deine eigenen Übungen und deine
-- deutschen Anleitungen (instructions_de) bleiben unberührt.
-- Die Übungen gehören dem ersten (einzigen) Nutzer in auth.users. Lege dein Konto
-- deshalb an, bevor du dieses Skript ausführst.

do $seed$
declare uid uuid;
begin
  select id into uid from auth.users order by created_at limit 1;
  if uid is null then
    raise exception 'Kein Nutzer in auth.users. Lege zuerst dein Konto an (Authentication > Users).';
  end if;

  insert into fit_exercises
    (user_id, source, source_id, name_en, name_de, primary_muscles, secondary_muscles, equipment, instructions_en)
  select uid, 'free-exercise-db', v.source_id, v.name_en, v.name_de, v.primary_muscles, v.secondary_muscles, v.equipment, v.instructions_en
  from (values
    ('3_4_Sit-Up', '3/4 Sit-Up', '3/4-Sit-up', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie down on the floor and secure your feet. Your legs should be bent at the knees.', 'Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.', 'Flex your hips and spine to raise your torso toward your knees.', 'At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Ab_Crunch_Machine', 'Ab Crunch Machine', 'Bauchpresse (Maschine)', array['abdominals']::text[], '{}'::text[], 'machine', array['Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.', 'At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.', 'After a second pause, slowly return to the starting position as you breathe in.', 'Repeat the movement for the prescribed amount of repetitions.']::text[]),
    ('Ab_Roller', 'Ab Roller', 'Bauchroller', array['abdominals']::text[], array['shoulders']::text[], 'other', array['Hold the Ab Roller with both hands and kneel on the floor.', 'Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[]),
    ('Advanced_Kettlebell_Windmill', 'Advanced Kettlebell Windmill', 'Kettlebell-Windmühle (fortgeschritten)', array['abdominals']::text[], array['glutes', 'hamstrings', 'shoulders']::text[], 'kettlebells', array['Clean and press a kettlebell overhead with one arm.', 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.', 'Lower yourself as far as possible.', 'Pause for a second and reverse the motion back to the starting position.']::text[]),
    ('Air_Bike', 'Air Bike', 'Air Bike', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.', 'Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.', 'Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.', 'Go back to the initial position as you breathe in.', 'Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.', 'Continue alternating in this manner until all of the recommended repetitions for each side have been completed.']::text[]),
    ('Alternate_Hammer_Curl', 'Alternate Hammer Curl', 'Hammer-Curl, wechselseitig', array['biceps']::text[], array['forearms']::text[], 'dumbbell', array['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.']::text[]),
    ('Alternate_Heel_Touchers', 'Alternate Heel Touchers', 'Fersen berühren, wechselseitig', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.', 'Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.', 'Now go back slowly to the starting position as you inhale.', 'Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.', 'Continue alternating sides in this manner until all prescribed repetitions are done.']::text[]),
    ('Alternate_Incline_Dumbbell_Curl', 'Alternate Incline Dumbbell Curl', 'Kurzhantel-Curl an der Schrägbank, wechselseitig', array['biceps']::text[], array['forearms']::text[], 'dumbbell', array['Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.', 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbell back to starting position as your breathe in.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.']::text[]),
    ('Alternating_Cable_Shoulder_Press', 'Alternating Cable Shoulder Press', 'Schulterdrücken am Kabelzug, wechselseitig', array['shoulders']::text[], array['triceps']::text[], 'cable', array['Move the cables to the bottom of the tower and select an appropriate weight.', 'Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.', 'Keeping your head and chest up, extend through the elbow to press one side directly over head.', 'After pausing at the top, return to the starting position and repeat on the opposite side.']::text[]),
    ('Alternating_Deltoid_Raise', 'Alternating Deltoid Raise', 'Schulterheben, wechselseitig', array['shoulders']::text[], '{}'::text[], 'dumbbell', array['In a standing position, hold a pair of dumbbells at your side.', 'Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.', 'Return the weights to your side.', 'On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.', 'Return the weights to the starting position and continue alternating to the front and side.']::text[]),
    ('Alternating_Floor_Press', 'Alternating Floor Press', 'Kurzhantel-Bodendrücken, wechselseitig', array['chest']::text[], array['abdominals', 'shoulders', 'triceps']::text[], 'kettlebells', array['Lie on the floor with two kettlebells next to your shoulders.', 'Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.', 'Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.', 'Raise the kettlebell and repeat on the opposite side.']::text[]),
    ('Alternating_Hang_Clean', 'Alternating Hang Clean', 'Umsetzen aus dem Hang, wechselseitig', array['hamstrings']::text[], array['biceps', 'calves', 'forearms', 'glutes', 'lower back', 'traps']::text[], 'kettlebells', array['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.', 'Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.']::text[]),
    ('Alternating_Kettlebell_Press', 'Alternating Kettlebell Press', 'Kettlebell-Drücken, wechselseitig', array['shoulders']::text[], array['triceps']::text[], 'kettlebells', array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.', 'Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .', 'Lower the pressed kettlebell to the starting position and immediately press with your other arm.']::text[]),
    ('Alternating_Kettlebell_Row', 'Alternating Kettlebell Row', 'Kettlebell-Rudern, wechselseitig', array['middle back']::text[], array['biceps', 'lats']::text[], 'kettlebells', array['Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.', 'Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.', 'Lower the kettlebell in the working arm and repeat with your other arm.']::text[]),
    ('Alternating_Renegade_Row', 'Alternating Renegade Row', 'Renegade Row, wechselseitig', array['middle back']::text[], array['abdominals', 'biceps', 'chest', 'lats', 'triceps']::text[], 'kettlebells', array['Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.', 'Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.', 'Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps.']::text[]),
    ('Anti-Gravity_Press', 'Anti-Gravity Press', 'Anti-Gravity-Press', array['shoulders']::text[], array['middle back', 'traps', 'triceps']::text[], 'barbell', array['Place a bar on the ground behind the head of an incline bench.', 'Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.', 'To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement.', 'Return to the starting position and repeat to complete the set.']::text[]),
    ('Arnold_Dumbbell_Press', 'Arnold Dumbbell Press', 'Arnold Press', array['shoulders']::text[], array['triceps']::text[], 'dumbbell', array['Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.', 'Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.', 'Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.', 'After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Around_The_Worlds', 'Around The Worlds', 'Around the World (Kurzhanteln)', array['chest']::text[], array['shoulders']::text[], 'dumbbell', array['Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.', 'Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.', 'Reverse the movement to return the weight to the starting position as you exhale.']::text[]),
    ('Atlas_Stone_Trainer', 'Atlas Stone Trainer', 'Atlas-Stein-Training', array['lower back']::text[], array['biceps', 'forearms', 'glutes', 'hamstrings', 'quadriceps']::text[], 'other', array['This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe.', 'Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips.', 'Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest.', 'Finish the movement by extending through your hips and knees to raise the weight as high as possible. The weight can be returned to the lap or to the ground for successive repetitions.']::text[]),
    ('Atlas_Stones', 'Atlas Stones', 'Atlas-Steine', array['lower back']::text[], array['abdominals', 'adductors', 'biceps', 'calves', 'forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps']::text[], 'other', array['Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.', 'Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.', 'As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.', 'Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible.']::text[]),
    ('Axle_Deadlift', 'Axle Deadlift', 'Kreuzheben mit dicker Achse', array['lower back']::text[], array['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps']::text[], 'other', array['Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.', 'With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.', 'After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[]),
    ('Back_Flyes_-_With_Bands', 'Back Flyes - With Bands', 'Reverse Flys mit Band', array['shoulders']::text[], array['middle back', 'triceps']::text[], 'bands', array['Run a band around a stationary post like that of a squat rack.', 'Grab the band by the handles and stand back so that the tension in the band rises.', 'Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.', 'As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.', 'After a pause, go back to the original position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Backward_Drag', 'Backward Drag', 'Rückwärts ziehen (Schlitten)', array['quadriceps']::text[], array['calves', 'forearms', 'glutes', 'hamstrings', 'lower back']::text[], 'other', array['Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.', 'Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible.']::text[]),
    ('Balance_Board', 'Balance Board', 'Balance-Board', array['calves']::text[], array['hamstrings', 'quadriceps']::text[], 'other', array['Place a balance board in front of you.', 'Stand up on it and try to balance yourself.', 'Hold the balance for as long as desired.']::text[]),
    ('Ball_Leg_Curl', 'Ball Leg Curl', 'Beinbeuger mit Gymnastikball', array['hamstrings']::text[], array['calves', 'glutes']::text[], 'exercise ball', array['Begin on the floor laying on your back with your feet on top of the ball.', 'Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.', 'Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.', 'Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.', 'After a brief pause, return to the starting position.']::text[]),
    ('Band_Assisted_Pull-Up', 'Band Assisted Pull-Up', 'Klimmzug mit Bandunterstützung', array['lats']::text[], array['abdominals', 'forearms', 'middle back']::text[], 'other', array['Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.', 'Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.', 'Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.', 'After a brief pause, return to the starting position.']::text[]),
    ('Band_Good_Morning', 'Band Good Morning', 'Good Morning mit Band', array['hamstrings']::text[], array['glutes', 'lower back']::text[], 'bands', array['Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.', 'Keeping your legs straight, extend through the hips to come to a near vertical position.', 'Ensure that you do not round your back as you go down back to the starting position.']::text[]),
    ('Band_Good_Morning_Pull_Through', 'Band Good Morning (Pull Through)', 'Good Morning mit Band (Pull-Through)', array['hamstrings']::text[], array['glutes', 'lower back']::text[], 'bands', array['Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.', 'Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.', 'Return to the starting position be driving through with the hips to come back to a standing position.']::text[]),
    ('Band_Hip_Adductions', 'Band Hip Adductions', 'Hüftadduktion mit Band', array['adductors']::text[], '{}'::text[], 'bands', array['Anchor a band around a solid post or other object.', 'Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.', 'Stand up straight and hold onto the post if needed. This will be your starting position.', 'Keeping the knee straight, raise your right legs out to the side as far as you can.', 'Return to the starting position and repeat for the desired rep count.', 'Switch sides.']::text[]),
    ('Band_Pull_Apart', 'Band Pull Apart', 'Band Pull-Apart', array['shoulders']::text[], array['middle back', 'traps']::text[], 'bands', array['Begin with your arms extended straight out in front of you, holding the band with both hands.', 'Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.', 'Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.', 'Pause as you complete the movement, returning to the starting position under control.']::text[]),
    ('Band_Skull_Crusher', 'Band Skull Crusher', 'Stirndrücken mit Band', array['triceps']::text[], '{}'::text[], 'bands', array['Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.', 'Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.', 'Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.']::text[]),
    ('Barbell_Ab_Rollout', 'Barbell Ab Rollout', 'Langhantel-Bauchroller', array['abdominals']::text[], array['lower back', 'shoulders']::text[], 'barbell', array['For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.', 'While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.', 'After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Ab_Rollout_-_On_Knees', 'Barbell Ab Rollout - On Knees', 'Langhantel-Bauchroller auf den Knien', array['abdominals']::text[], array['lower back', 'shoulders']::text[], 'barbell', array['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.', 'Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[]),
    ('Barbell_Bench_Press_-_Medium_Grip', 'Barbell Bench Press - Medium Grip', 'Langhantel-Bankdrücken, mittlerer Griff', array['chest']::text[], array['shoulders', 'triceps']::text[], 'barbell', array['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.', 'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[]),
    ('Barbell_Curl', 'Barbell Curl', 'Langhantel-Curl', array['biceps']::text[], array['forearms']::text[], 'barbell', array['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Curls_Lying_Against_An_Incline', 'Barbell Curls Lying Against An Incline', 'Langhantel-Curl, bäuchlings an der Schrägbank', array['biceps']::text[], '{}'::text[], 'barbell', array['Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.', 'While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.', 'After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Deadlift', 'Barbell Deadlift', 'Langhantel-Kreuzheben', array['lower back']::text[], array['calves', 'forearms', 'glutes', 'hamstrings', 'lats', 'middle back', 'quadriceps', 'traps']::text[], 'barbell', array['Stand in front of a loaded barbell.', 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.', 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.', 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.', 'Perform the amount of repetitions prescribed in the program.']::text[]),
    ('Barbell_Full_Squat', 'Barbell Full Squat', 'Langhantel-Kniebeuge (tief)', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'lower back']::text[], 'barbell', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.', 'Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Glute_Bridge', 'Barbell Glute Bridge', 'Langhantel-Beckenheben', array['glutes']::text[], array['calves', 'hamstrings']::text[], 'barbell', array['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.', 'Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.', 'Extend as far as possible, then reverse the motion to return to the starting position.']::text[]),
    ('Barbell_Guillotine_Bench_Press', 'Barbell Guillotine Bench Press', 'Guillotine-Bankdrücken (Langhantel)', array['chest']::text[], array['shoulders', 'triceps']::text[], 'barbell', array['Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.', 'As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[]),
    ('Barbell_Hack_Squat', 'Barbell Hack Squat', 'Hack Squat mit Langhantel', array['quadriceps']::text[], array['calves', 'forearms', 'hamstrings']::text[], 'barbell', array['Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', 'While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.', 'Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Hip_Thrust', 'Barbell Hip Thrust', 'Langhantel-Hip-Thrust', array['glutes']::text[], array['calves', 'hamstrings']::text[], 'barbell', array['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.', 'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.', 'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.']::text[]),
    ('Barbell_Incline_Bench_Press_-_Medium_Grip', 'Barbell Incline Bench Press - Medium Grip', 'Langhantel-Schrägbankdrücken, mittlerer Griff', array['chest']::text[], array['shoulders', 'triceps']::text[], 'barbell', array['Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on you upper chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[]),
    ('Barbell_Incline_Shoulder_Raise', 'Barbell Incline Shoulder Raise', 'Langhantel-Schulterheben an der Schrägbank', array['shoulders']::text[], array['chest']::text[], 'barbell', array['Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.', 'While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.', 'Bring back the bar to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Lunge', 'Barbell Lunge', 'Langhantel-Ausfallschritt', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'barbell', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[]),
    ('Barbell_Rear_Delt_Row', 'Barbell Rear Delt Row', 'Langhantel-Rudern für die hintere Schulter', array['shoulders']::text[], array['biceps', 'lats', 'middle back']::text[], 'barbell', array['Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.', 'Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter "T". Now you are ready to begin the exercise.', 'While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.', 'Slowly go back to the initial position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Rollout_from_Bench', 'Barbell Rollout from Bench', 'Langhantel-Rollout von der Bank', array['abdominals']::text[], array['glutes', 'hamstrings', 'lats', 'shoulders']::text[], 'barbell', array['Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.', 'To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.', 'When the bar has been moved as far forward as possible, return to the starting position.']::text[]),
    ('Barbell_Seated_Calf_Raise', 'Barbell Seated Calf Raise', 'Sitzendes Wadenheben mit Langhantel', array['calves']::text[], '{}'::text[], 'barbell', array['Place a block about 12 inches in front of a flat bench.', 'Sit on the bench and place the ball of your feet on the block.', 'Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.', 'Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.', 'After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Shoulder_Press', 'Barbell Shoulder Press', 'Langhantel-Schulterdrücken', array['shoulders']::text[], array['chest', 'triceps']::text[], 'barbell', array['Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).', 'Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the shoulders slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Shrug', 'Barbell Shrug', 'Langhantel-Schulterzucken', array['traps']::text[], '{}'::text[], 'barbell', array['Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Shrug_Behind_The_Back', 'Barbell Shrug Behind The Back', 'Langhantel-Schulterzucken hinter dem Rücken', array['traps']::text[], array['forearms', 'middle back']::text[], 'barbell', array['Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.', 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Side_Bend', 'Barbell Side Bend', 'Langhantel-Seitbeugen', array['abdominals']::text[], array['lower back']::text[], 'barbell', array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.', 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.', 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Side_Split_Squat', 'Barbell Side Split Squat', 'Langhantel-Seitausfallschritt (Side Split Squat)', array['quadriceps']::text[], array['calves', 'hamstrings', 'lower back']::text[], 'barbell', array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.', 'Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.', 'Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.', 'After performing the recommended amount of reps, repeat the movement with the opposite leg.']::text[]),
    ('Barbell_Squat', 'Barbell Squat', 'Langhantel-Kniebeuge', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'lower back']::text[], 'barbell', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Squat_To_A_Bench', 'Barbell Squat To A Bench', 'Langhantel-Kniebeuge auf die Bank', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'lower back']::text[], 'barbell', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.', '', 'Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Barbell_Step_Ups', 'Barbell Step Ups', 'Langhantel-Step-ups', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'quadriceps']::text[], 'barbell', array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[]),
    ('Barbell_Walking_Lunge', 'Barbell Walking Lunge', 'Langhantel-Gehende Ausfallschritte', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'barbell', array['Begin standing with your feet shoulder width apart and a barbell across your upper back.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[]),
    ('Battling_Ropes', 'Battling Ropes', 'Battle Ropes', array['shoulders']::text[], array['chest', 'forearms']::text[], 'other', array['For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.', 'Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.', 'As you let that arm drop to the starting position, raise the opposite side.', 'Continue alternating your left and right arms, whipping the ropes up and down as fast as you can.']::text[]),
    ('Bear_Crawl_Sled_Drags', 'Bear Crawl Sled Drags', 'Bear Crawl mit Schlitten', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'other', array['Wearing either a harness or a loose weight belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that your hands are on the ground. Your back should be flat and knees bent. This is your starting position.', 'Begin by driving with legs, alternating left and right. Use your hands to maintain balance and to help pull. Try to keep your back flat as you move over a given distance.']::text[]),
    ('Bench_Dips', 'Bench Dips', 'Bankdips', array['triceps']::text[], array['chest', 'shoulders']::text[], 'body only', array['For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.', 'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.', 'Using your triceps to bring your torso up again, lift yourself back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Bench_Press_-_Powerlifting', 'Bench Press - Powerlifting', 'Bankdrücken (Powerlifting)', array['triceps']::text[], array['chest', 'forearms', 'lats', 'shoulders']::text[], 'barbell', array['Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', 'However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.', 'Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.', 'Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[]),
    ('Bench_Press_-_With_Bands', 'Bench Press - With Bands', 'Bankdrücken mit Bändern', array['chest']::text[], array['shoulders', 'triceps']::text[], 'bands', array['Using a flat bench secure a band under the leg of the bench that is nearest to your head.', 'Once the band is secure, grab it by both handles and lie down on the bench.', 'Extend your arms so that you are holding the band handles in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.', 'As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[]),
    ('Bench_Press_with_Chains', 'Bench Press with Chains', 'Bankdrücken mit Ketten', array['triceps']::text[], array['chest', 'lats', 'shoulders']::text[], 'barbell', array['Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.', 'Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.', 'Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.', 'Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[]),
    ('Bent-Arm_Barbell_Pullover', 'Bent-Arm Barbell Pullover', 'Langhantel-Überzug mit gebeugten Armen', array['lats']::text[], array['chest', 'lats', 'shoulders', 'triceps']::text[], 'barbell', array['Lie on a flat bench with a barbell using a shoulder grip width.', 'Hold the bar straight over your chest with a bend in your arms. This will be your starting position.', 'While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.', 'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[]),
    ('Bent-Arm_Dumbbell_Pullover', 'Bent-Arm Dumbbell Pullover', 'Kurzhantel-Überzug mit gebeugten Armen', array['chest']::text[], array['lats', 'shoulders', 'triceps']::text[], 'dumbbell', array['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.', 'Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.', 'While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.', 'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[]),
    ('Bent-Knee_Hip_Raise', 'Bent-Knee Hip Raise', 'Beinheben mit gebeugten Knien', array['abdominals']::text[], '{}'::text[], 'body only', array['Lay flat on the floor with your arms next to your sides.', 'Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.', 'Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.', 'Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Bent_Over_Barbell_Row', 'Bent Over Barbell Row', 'Vorgebeugtes Langhantelrudern', array['middle back']::text[], array['biceps', 'lats', 'shoulders']::text[], 'barbell', array['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.', 'Then inhale and slowly lower the barbell back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench', 'Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'Vorgebeugtes Kurzhantel-Reverse-Fly, Kopf auf der Bank', array['shoulders']::text[], '{}'::text[], 'dumbbell', array['Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.', 'While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.', 'Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.', 'After a one second contraction at the top, slowly lower the dumbbells back to the starting position.', 'Repeat the recommended amount of repetitions.']::text[]),
    ('Bent_Over_Low-Pulley_Side_Lateral', 'Bent Over Low-Pulley Side Lateral', 'Vorgebeugtes Seitheben am unteren Kabelzug', array['shoulders']::text[], array['lower back', 'middle back', 'traps']::text[], 'cable', array['Select a weight and hold the handle of the low pulley with your right hand.', 'Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.', 'Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.', 'Slowly lower the weight back to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions and repeat the movement with the other arm.']::text[]),
    ('Bent_Over_One-Arm_Long_Bar_Row', 'Bent Over One-Arm Long Bar Row', 'Vorgebeugtes einarmiges Rudern mit langer Stange', array['middle back']::text[], array['biceps', 'lats', 'lower back', 'traps']::text[], 'barbell', array['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.', 'Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.', 'Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.', 'Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.', 'Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).', 'Repeat for the recommended amount of repetitions and switch arms.']::text[]),
    ('Bent_Over_Two-Arm_Long_Bar_Row', 'Bent Over Two-Arm Long Bar Row', 'Vorgebeugtes beidarmiges Rudern mit langer Stange', array['middle back']::text[], array['biceps', 'lats']::text[], 'barbell', array['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.', 'Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.', 'Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.', 'Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Use a stirrup or double handle cable attachment by hooking it under the end of the bar.', 'Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Bent_Over_Two-Dumbbell_Row', 'Bent Over Two-Dumbbell Row', 'Vorgebeugtes Kurzhantelrudern (beidarmig)', array['middle back']::text[], array['biceps', 'lats', 'shoulders']::text[], 'dumbbell', array['With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Bent_Over_Two-Dumbbell_Row_With_Palms_In', 'Bent Over Two-Dumbbell Row With Palms In', 'Vorgebeugtes Kurzhantelrudern, neutraler Griff', array['middle back']::text[], array['biceps', 'lats']::text[], 'dumbbell', array['With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Bent_Press', 'Bent Press', 'Bent Press', array['abdominals']::text[], array['glutes', 'hamstrings', 'lower back', 'quadriceps', 'shoulders', 'triceps']::text[], 'kettlebells', array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.', 'Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.', 'Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions.']::text[]),
    ('Board_Press', 'Board Press', 'Board Press', array['triceps']::text[], array['chest', 'forearms', 'lats', 'shoulders']::text[], 'barbell', array['Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.', 'Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', 'You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.', 'Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[]),
    ('Body-Up', 'Body-Up', 'Body-Up', array['triceps']::text[], array['abdominals', 'forearms']::text[], 'body only', array['Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.', 'Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.', 'Slowly lower your forearms back to the ground by allowing the elbows to flex.', 'Repeat.']::text[]),
    ('Body_Tricep_Press', 'Body Tricep Press', 'Trizepsdrücken mit Körpergewicht', array['triceps']::text[], '{}'::text[], 'body only', array['Position a bar in a rack at chest height.', 'Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.', 'Begin by flexing the elbow, lowering yourself towards the bar.', 'Pause, and then reverse the motion by extending the elbows.', 'Progress from bodyweight by adding chains over your shoulders.']::text[]),
    ('Bodyweight_Flyes', 'Bodyweight Flyes', 'Fliegende mit Körpergewicht', array['chest']::text[], array['abdominals', 'shoulders', 'triceps']::text[], 'e-z curl bar', array['Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.', 'Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.', 'Place your hands on the bars. This will be your starting position.', 'Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.', 'After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement.']::text[]),
    ('Bodyweight_Mid_Row', 'Bodyweight Mid Row', 'Körpergewichts-Rudern (mittlere Position)', array['middle back']::text[], array['biceps', 'lats']::text[], 'other', array['Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.', 'Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.', 'After a brief pause, return to the starting position.']::text[]),
    ('Bodyweight_Squat', 'Bodyweight Squat', 'Kniebeuge mit Körpergewicht', array['quadriceps']::text[], array['glutes', 'hamstrings']::text[], 'body only', array['Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.', 'Begin the movement by flexing your knees and hips, sitting back with your hips.', 'Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.']::text[]),
    ('Bodyweight_Walking_Lunge', 'Bodyweight Walking Lunge', 'Gehende Ausfallschritte mit Körpergewicht', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], null, array['Begin standing with your feet shoulder width apart and your hands on your hips.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[]),
    ('Bosu_Ball_Cable_Crunch_With_Side_Bends', 'Bosu Ball Cable Crunch With Side Bends', 'Kabel-Crunch auf dem Bosu Ball mit Seitbeuge', array['abdominals']::text[], '{}'::text[], 'cable', array['Connect a standard handle to each arm of a cable machine, and position them in the most downward position.', 'Grab a Bosu Ball and position it in front and center of the cable machine.', 'Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.', 'With both hands, reach back and grab the handle of each cable.', 'With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.', 'Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.', 'Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.', 'Repeat the same series of movements to failure.', 'Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.', 'Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques.']::text[]),
    ('Bottoms-Up_Clean_From_The_Hang_Position', 'Bottoms-Up Clean From The Hang Position', 'Bottoms-Up-Umsetzen aus dem Hang', array['forearms']::text[], array['biceps', 'shoulders']::text[], 'kettlebells', array['Initiate the exercise by standing upright with a kettlebell in one hand.', 'Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.']::text[]),
    ('Bottoms_Up', 'Bottoms Up', 'Bottoms Up', array['abdominals']::text[], '{}'::text[], 'body only', array['Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.', 'To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.', 'After a brief pause, return to the starting position.']::text[]),
    ('Box_Squat', 'Box Squat', 'Box-Kniebeuge', array['quadriceps']::text[], array['adductors', 'calves', 'glutes', 'hamstrings', 'lower back']::text[], 'barbell', array['The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[]),
    ('Box_Squat_with_Bands', 'Box Squat with Bands', 'Box-Kniebeuge mit Bändern', array['quadriceps']::text[], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings', 'lower back']::text[], 'barbell', array['Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don''t move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.']::text[]),
    ('Box_Squat_with_Chains', 'Box Squat with Chains', 'Box-Kniebeuge mit Ketten', array['quadriceps']::text[], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings', 'lower back']::text[], 'barbell', array['Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.', 'To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[]),
    ('Bradford_Rocky_Presses', 'Bradford/Rocky Presses', 'Bradford-/Rocky-Press', array['shoulders']::text[], array['triceps']::text[], 'barbell', array['Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position.', 'Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms.', 'Now lower the bar down to the back of the head slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Lower the bar down to the starting position slowly as you inhale. This is one repetition.', 'Alternate in this manner until you complete the recommended amount of repetitions.']::text[]),
    ('Butt-Ups', 'Butt-Ups', 'Butt-Ups', array['abdominals']::text[], '{}'::text[], 'body only', array['Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle.', 'Arch your back slightly out rather than keeping your back completely straight.', 'Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of the movement.', 'Lower back down slowly to your starting position as you breathe in. Tip: Don''t let your back sag downwards.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Butt_Lift_Bridge', 'Butt Lift (Bridge)', 'Beckenheben (Brücke)', array['glutes']::text[], array['hamstrings']::text[], 'body only', array['Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.', 'Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.', 'Slowly go back to the starting position as you breathe in.']::text[]),
    ('Butterfly', 'Butterfly', 'Butterfly (Maschine)', array['chest']::text[], '{}'::text[], 'machine', array['Sit on the machine with your back flat on the pad.', 'Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.', 'Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.', 'Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cable_Chest_Press', 'Cable Chest Press', 'Brustdrücken am Kabelzug', array['chest']::text[], array['shoulders', 'triceps']::text[], 'cable', array['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.', 'After pausing at full extension, return to th starting position, keeping tension on the cables.', 'You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands.']::text[]),
    ('Cable_Crossover', 'Cable Crossover', 'Cable Crossover', array['chest']::text[], array['shoulders']::text[], 'cable', array['To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.', 'Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.']::text[]),
    ('Cable_Crunch', 'Cable Crunch', 'Kabel-Crunch', array['abdominals']::text[], '{}'::text[], 'cable', array['Kneel below a high pulley that contains a rope attachment.', 'Grasp cable rope attachment and lower the rope until your hands are placed next to your face.', 'Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.', 'With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.', 'Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cable_Deadlifts', 'Cable Deadlifts', 'Kreuzheben am Kabelzug', array['quadriceps']::text[], array['forearms', 'glutes', 'hamstrings', 'lower back']::text[], 'cable', array['Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.', 'To begin, squat down be flexing your hips and knees until you can reach the handles.', 'After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.', 'After reaching a full standing position, Return to the starting position and repeat.']::text[]),
    ('Cable_Hammer_Curls_-_Rope_Attachment', 'Cable Hammer Curls - Rope Attachment', 'Hammer-Curl am Kabelzug (Seil)', array['biceps']::text[], '{}'::text[], 'cable', array['Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.', 'Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.', 'Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.', 'Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.', 'After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cable_Hip_Adduction', 'Cable Hip Adduction', 'Hüftadduktion am Kabelzug', array['quadriceps']::text[], '{}'::text[], 'cable', array['Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.', 'Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.', 'Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.', 'Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.', 'Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg.']::text[]),
    ('Cable_Incline_Pushdown', 'Cable Incline Pushdown', 'Schräges Trizepsdrücken am Kabelzug', array['lats']::text[], '{}'::text[], 'cable', array['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.', 'Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position.', 'Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the movement.', 'Slowly go back to the starting position using your lats and hold the contraction once you reach the starting position. Breathe out during the execution of this movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cable_Incline_Triceps_Extension', 'Cable Incline Triceps Extension', 'Schräge Trizeps-Extension am Kabelzug', array['triceps']::text[], '{}'::text[], 'cable', array['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.', 'Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.', 'Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.', 'Slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cable_Internal_Rotation', 'Cable Internal Rotation', 'Innenrotation am Kabelzug', array['shoulders']::text[], '{}'::text[], 'cable', array['Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead.', 'Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.', 'Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times.', 'Slowly go back to the initial position.', 'Repeat for the recommended amount of repetitions and then repeat the movement with the next arm.']::text[])
  ) as v(source_id, name_en, name_de, primary_muscles, secondary_muscles, equipment, instructions_en)
  on conflict (user_id, source, source_id) do update set
    name_en = excluded.name_en,
    name_de = excluded.name_de,
    primary_muscles = excluded.primary_muscles,
    secondary_muscles = excluded.secondary_muscles,
    equipment = excluded.equipment,
    instructions_en = excluded.instructions_en;

  insert into fit_exercises
    (user_id, source, source_id, name_en, name_de, primary_muscles, secondary_muscles, equipment, instructions_en)
  select uid, 'free-exercise-db', v.source_id, v.name_en, v.name_de, v.primary_muscles, v.secondary_muscles, v.equipment, v.instructions_en
  from (values
    ('Cable_Iron_Cross', 'Cable Iron Cross', 'Iron Cross am Kabelzug', array['chest']::text[], '{}'::text[], 'cable', array['Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.', 'Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a "T". This will be your starting position.', 'Keeping the elbows extended, pull your arms straight to your sides.', 'Return your arms back to the starting position after a pause at the peak contraction.', 'Continue the movement for the prescribed number of repetitions.']::text[]),
    ('Cable_Judo_Flip', 'Cable Judo Flip', 'Judo Flip am Kabelzug', array['abdominals']::text[], '{}'::text[], 'cable', array['Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands.', 'Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip.', 'Shift your weight between your feet as you twist and crunch forward, pulling the cable downward.', 'Return to the starting position and repeat until failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[]),
    ('Cable_Lying_Triceps_Extension', 'Cable Lying Triceps Extension', 'Liegende Trizeps-Extension am Kabelzug', array['triceps']::text[], '{}'::text[], 'cable', array['Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.', 'With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.', 'Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.', 'Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.', 'Hold for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[]),
    ('Cable_One_Arm_Tricep_Extension', 'Cable One Arm Tricep Extension', 'Einarmige Trizeps-Extension am Kabelzug', array['triceps']::text[], '{}'::text[], 'cable', array['With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.', 'Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.', 'As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.', 'Squeeze the triceps and hold for a second in this contracted position.', 'Slowly return the handle to the starting position.', 'Repeat for the recommended amount of repetitions and then perform the same movement with the other arm.']::text[]),
    ('Cable_Preacher_Curl', 'Cable Preacher Curl', 'Scott-Curl am Kabelzug', array['biceps']::text[], array['forearms']::text[], 'cable', array['Place a preacher bench about 2 feet in front of a pulley machine.', 'Attach a straight bar to the low pulley.', 'Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.', 'Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.', 'Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.', 'Now slowly lower the weight to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cable_Rear_Delt_Fly', 'Cable Rear Delt Fly', 'Reverse Fly am Kabelzug', array['shoulders']::text[], '{}'::text[], 'cable', array['Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.', 'Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.', 'Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.', 'Pause at the end of the motion before returning the handles to the start position.']::text[]),
    ('Cable_Reverse_Crunch', 'Cable Reverse Crunch', 'Reverse Crunch am Kabelzug', array['abdominals']::text[], '{}'::text[], 'cable', array['Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.', 'Sit down with your feet toward the pulley and attach the cable to your ankles.', 'Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.', 'With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.', 'Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.', 'Repeat the same movement to failure.']::text[]),
    ('Cable_Rope_Overhead_Triceps_Extension', 'Cable Rope Overhead Triceps Extension', 'Trizeps-Extension über Kopf am Kabelzug (Seil)', array['triceps']::text[], '{}'::text[], 'cable', array['Attach a rope to the bottom pulley of the pulley machine.', 'Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.', 'Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.', 'Return to the starting position by flexing your triceps as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cable_Rope_Rear-Delt_Rows', 'Cable Rope Rear-Delt Rows', 'Rudern zur hinteren Schulter am Kabelzug (Seil)', array['shoulders']::text[], array['biceps', 'middle back']::text[], 'cable', array['Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back.', 'Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out.', 'Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position.', 'Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out to the sides. Continue this motion as you exhale until the elbows travel slightly behind the back. Tip: Keep your upper arms horizontal, perpendicular to the torso and parallel to the floor throughout the motion.', 'Go back to the initial position where the arms are extended and the shoulders are stretched forward. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cable_Russian_Twists', 'Cable Russian Twists', 'Russian Twist am Kabelzug', array['abdominals']::text[], '{}'::text[], 'cable', array['Connect a standard handle attachment, and position the cable to a middle pulley position.', 'Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.', 'Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.', 'Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.', 'Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.', 'Repeat the same movement to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[]),
    ('Cable_Seated_Crunch', 'Cable Seated Crunch', 'Sitzender Kabel-Crunch', array['abdominals']::text[], '{}'::text[], 'cable', array['Seat on a flat bench with your back facing a high pulley.', 'Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.', 'With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.', 'As you inhale, go back to the initial position slowly.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cable_Seated_Lateral_Raise', 'Cable Seated Lateral Raise', 'Sitzendes Seitheben am Kabelzug', array['shoulders']::text[], array['middle back', 'traps']::text[], 'cable', array['Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.', 'Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.', 'Bend forward while keeping your back flat and rest your torso on the thighs.', 'Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.', 'While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.', 'Slowly lower your arms to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise.']::text[]),
    ('Cable_Shoulder_Press', 'Cable Shoulder Press', 'Schulterdrücken am Kabelzug', array['shoulders']::text[], array['triceps']::text[], 'cable', array['Move the cables to the bottom of the towers and select an appropriate weight.', 'Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.', 'Keeping your head and chest up, extend through the elbow to press the handles directly over head.', 'After pausing at the top, return to the starting position and repeat.']::text[]),
    ('Cable_Shrugs', 'Cable Shrugs', 'Schulterzucken am Kabelzug', array['traps']::text[], '{}'::text[], 'cable', array['Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.', 'Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.', 'Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.', 'Lower the bar back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cable_Wrist_Curl', 'Cable Wrist Curl', 'Handgelenk-Curl am Kabelzug', array['forearms']::text[], '{}'::text[], 'cable', array['Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.', 'Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.', 'Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Calf-Machine_Shoulder_Shrug', 'Calf-Machine Shoulder Shrug', 'Schulterzucken an der Wadenmaschine', array['traps']::text[], '{}'::text[], 'machine', array['Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.', 'Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.', 'Slowly return to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Calf_Press', 'Calf Press', 'Wadendrücken', array['calves']::text[], '{}'::text[], 'machine', array['Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.', 'Select an appropriate weight, and grasp the handles. This will be your starting position.', 'Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible.', 'After a brief pause, reverse the motion and repeat.']::text[]),
    ('Calf_Press_On_The_Leg_Press_Machine', 'Calf Press On The Leg Press Machine', 'Wadendrücken an der Beinpresse', array['calves']::text[], '{}'::text[], 'machine', array['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Calf_Raise_On_A_Dumbbell', 'Calf Raise On A Dumbbell', 'Wadenheben auf einer Kurzhantel', array['calves']::text[], '{}'::text[], 'dumbbell', array['Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.', 'Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.', 'Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward.', 'Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Calf_Raises_-_With_Bands', 'Calf Raises - With Bands', 'Wadenheben mit Band', array['calves']::text[], '{}'::text[], 'bands', array['Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.', 'While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.', 'Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.', 'After a one second contraction, slowly go back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Car_Deadlift', 'Car Deadlift', 'Auto-Kreuzheben', array['quadriceps']::text[], array['forearms', 'glutes', 'hamstrings', 'lower back', 'traps']::text[], 'other', array['This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs.', 'Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With your feet and your grip set, take a big breath and then lower your hips and flex the knees.', 'Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.', 'Lower the weight by bending at the hips and guiding it to the floor.']::text[]),
    ('Car_Drivers', 'Car Drivers', 'Car Drivers', array['shoulders']::text[], array['forearms']::text[], 'barbell', array['While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.', 'Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.', 'Reverse the motion, turning it all the way to the opposite side.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Chain_Handle_Extension', 'Chain Handle Extension', 'Chain-Handle-Extension', array['triceps']::text[], '{}'::text[], 'other', array['You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.', 'Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.', 'Pause at the lockout, and reverse the motion to return to the starting position.']::text[]),
    ('Chain_Press', 'Chain Press', 'Chain Press', array['chest']::text[], array['shoulders', 'triceps']::text[], 'other', array['Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position.', 'Lower the chains by flexing the elbows, unloading some of the chain onto the floor.', 'Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout.']::text[]),
    ('Chair_Squat', 'Chair Squat', 'Stuhl-Kniebeuge', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'machine', array['To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders.', 'Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs.', 'Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.', 'Slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees.', 'Begin to raise the bar as you exhale by pushing the floor with the heels of your feet, extending the knees and returning to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Chin-Up', 'Chin-Up', 'Klimmzug im Untergriff', array['lats']::text[], array['biceps', 'forearms', 'middle back']::text[], 'body only', array['Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.', 'As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[]),
    ('Circus_Bell', 'Circus Bell', 'Circus Bell', array['shoulders']::text[], array['forearms', 'glutes', 'hamstrings', 'lower back', 'traps', 'triceps']::text[], 'other', array['The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands.', 'Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand.', 'Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip by flexing the knees, and the drive upwards as you extend the dumbbell overhead, leaning slightly away from it as you do so.', 'Carefully guide the bell back to the floor, keeping it under control as much as possible. It is best to perform this event on a thick rubber mat to prevent damage to the floor.']::text[]),
    ('Clean', 'Clean', 'Umsetzen', array['hamstrings']::text[], array['calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps']::text[], 'barbell', array['With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', '', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[]),
    ('Clean_Deadlift', 'Clean Deadlift', 'Kreuzheben (Umsetz-Variante)', array['hamstrings']::text[], array['forearms', 'glutes', 'lower back', 'middle back', 'quadriceps', 'traps']::text[], 'barbell', array['Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.', 'Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.', 'After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended.']::text[]),
    ('Clean_Pull', 'Clean Pull', 'Clean Pull', array['quadriceps']::text[], array['forearms', 'glutes', 'hamstrings', 'lower back', 'traps']::text[], 'barbell', array['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.']::text[]),
    ('Clean_Shrug', 'Clean Shrug', 'Clean Shrug', array['traps']::text[], array['forearms', 'shoulders']::text[], 'barbell', array['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.', 'Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.']::text[]),
    ('Clean_and_Jerk', 'Clean and Jerk', 'Umsetzen und Stoßen', array['shoulders']::text[], array['abdominals', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps', 'triceps']::text[], 'barbell', array['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.', 'The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.', 'Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.', 'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position.']::text[]),
    ('Clean_and_Press', 'Clean and Press', 'Umsetzen und Drücken', array['shoulders']::text[], array['abdominals', 'calves', 'glutes', 'hamstrings', 'lower back', 'middle back', 'quadriceps', 'shoulders', 'traps', 'triceps']::text[], 'barbell', array['Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.', 'Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.', 'As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.', 'At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.', 'As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.', 'Stand to full height, holding the bar in the clean position.', 'Without moving your feet, press the bar overhead as you exhale. Lower the bar under control .']::text[]),
    ('Clean_from_Blocks', 'Clean from Blocks', 'Umsetzen von Blöcken', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'shoulders', 'traps']::text[], 'barbell', array['With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out.', 'As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out. Aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position. Return the weight to the boxes for the next rep.']::text[]),
    ('Clock_Push-Up', 'Clock Push-Up', 'Uhr-Liegestütz (Clock Push-Up)', array['chest']::text[], array['shoulders', 'triceps']::text[], 'body only', array['Move into a prone position on the floor, supporting your weight on your hands and toes.', 'Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.', 'Descend by flexing at the elbow, lowering your chest toward the ground.', 'At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side.', 'As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.', 'Return to the starting position and repeat the exercise, working all the way around until you are back where you started.']::text[]),
    ('Close-Grip_Barbell_Bench_Press', 'Close-Grip Barbell Bench Press', 'Enges Langhantel-Bankdrücken', array['triceps']::text[], array['chest', 'shoulders']::text[], 'barbell', array['Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[]),
    ('Close-Grip_Dumbbell_Press', 'Close-Grip Dumbbell Press', 'Enges Kurzhantel-Drücken', array['triceps']::text[], array['chest', 'shoulders']::text[], 'dumbbell', array['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.', 'Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.', 'Initiate the movement by lowering the dumbbell to your chest.', 'Return to the starting position by extending the elbows.']::text[]),
    ('Close-Grip_EZ-Bar_Curl_with_Band', 'Close-Grip EZ-Bar Curl with Band', 'SZ-Stangen-Curl mit Band, enger Griff', array['biceps']::text[], array['forearms']::text[], 'e-z curl bar', array['Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.', 'While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Close-Grip_EZ-Bar_Press', 'Close-Grip EZ-Bar Press', 'SZ-Stangen-Drücken, enger Griff', array['triceps']::text[], array['chest', 'shoulders']::text[], 'e-z curl bar', array['Lie on a flat bench with an EZ bar loaded to an appropriate weight.', 'Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.', 'Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.', 'Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.', 'Repeat.']::text[]),
    ('Close-Grip_EZ_Bar_Curl', 'Close-Grip EZ Bar Curl', 'SZ-Stangen-Curl, enger Griff', array['biceps']::text[], array['forearms']::text[], 'barbell', array['Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Close-Grip_Front_Lat_Pulldown', 'Close-Grip Front Lat Pulldown', 'Latziehen zur Brust, enger Griff', array['lats']::text[], array['biceps', 'middle back', 'shoulders']::text[], 'cable', array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.', 'After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', '6. Repeat this motion for the prescribed amount of repetitions.']::text[]),
    ('Close-Grip_Push-Up_off_of_a_Dumbbell', 'Close-Grip Push-Up off of a Dumbbell', 'Enge Liegestütze auf einer Kurzhantel', array['triceps']::text[], array['abdominals', 'chest', 'shoulders']::text[], 'body only', array['Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position.', 'Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag.', 'Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step.', 'After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
    ('Close-Grip_Standing_Barbell_Curl', 'Close-Grip Standing Barbell Curl', 'Stehender Langhantel-Curl, enger Griff', array['biceps']::text[], array['forearms']::text[], 'barbell', array['Hold a barbell with both hands, palms up and a few inches apart.', 'Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement.', 'Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip: Avoid bending the back or using swinging motions as you lift the weight. Only the forearms should move.', 'Slowly go back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cocoons', 'Cocoons', 'Cocoons', array['abdominals']::text[], '{}'::text[], 'body only', array['Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.', 'To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.', 'After a brief pause, return to the starting position.']::text[]),
    ('Conans_Wheel', 'Conan''s Wheel', 'Conan''s Wheel', array['quadriceps']::text[], array['abdominals', 'biceps', 'calves', 'forearms', 'lower back', 'shoulders', 'traps']::text[], 'other', array['With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms.', 'Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns.']::text[]),
    ('Concentration_Curls', 'Concentration Curls', 'Konzentrationscurls', array['biceps']::text[], array['forearms']::text[], 'dumbbell', array['Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.', 'Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.', 'Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm.']::text[]),
    ('Cross-Body_Crunch', 'Cross-Body Crunch', 'Cross-Body-Crunch', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie flat on your back and bend your knees about 60 degrees.', 'Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.', 'Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.', 'Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.', 'Continue alternating in this manner until all prescribed repetitions are done.']::text[]),
    ('Cross_Body_Hammer_Curl', 'Cross Body Hammer Curl', 'Cross-Body-Hammer-Curl', array['biceps']::text[], array['forearms']::text[], 'dumbbell', array['Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.', 'While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.', 'Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.', 'Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.']::text[]),
    ('Cross_Over_-_With_Bands', 'Cross Over - With Bands', 'Cable Crossover mit Bändern', array['chest']::text[], array['biceps', 'shoulders']::text[], 'bands', array['Secure an exercise band around a stationary post.', 'While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.', 'Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.', 'While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.', 'Slowly return to the starting position as you inhale.', 'Perform for the recommended amount of repetitions.']::text[]),
    ('Crucifix', 'Crucifix', 'Crucifix (Kruzifix-Halten)', array['shoulders']::text[], array['forearms']::text[], 'other', array['In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different.', 'Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be heavy enough that you fail in 30-60 seconds.']::text[]),
    ('Crunch_-_Hands_Overhead', 'Crunch - Hands Overhead', 'Crunch, Hände über dem Kopf', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.', 'Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position.', 'Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don''t move them forward from that position. Exhale as you perform this portion of the movement and hold the contraction for a second.', 'Slowly lower down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Crunch_-_Legs_On_Exercise_Ball', 'Crunch - Legs On Exercise Ball', 'Crunch, Beine auf dem Gymnastikball', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.', 'Place your feet three to four inches apart and point your toes inward so they touch.', 'Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.', 'Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.', 'Slowly go back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Crunches', 'Crunches', 'Crunches', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.', 'Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.', 'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.', 'After the one second contraction, begin to come down slowly again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Cuban_Press', 'Cuban Press', 'Cuban Press', array['shoulders']::text[], array['traps']::text[], 'dumbbell', array['Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the "scarecrow" position. This will be your starting position.', 'To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.', 'Now press the dumbbells by extending at the elbows, straightening your arms overhead.', 'Return to the starting position as you breathe in by reversing the steps.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dead_Bug', 'Dead Bug', 'Dead Bug', array['abdominals']::text[], '{}'::text[], 'body only', array['Begin lying on your back with your hands extended above you toward the ceiling.', 'Bring your feet, knees, and hips up to 90 degrees.', 'Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.', 'Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.', 'Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.', 'Stay tight and return the working leg to the starting position.', 'Repeat on the opposite side, alternating until the set is complete.']::text[]),
    ('Deadlift_with_Bands', 'Deadlift with Bands', 'Kreuzheben mit Bändern', array['lower back']::text[], array['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps']::text[], 'barbell', array['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[]),
    ('Deadlift_with_Chains', 'Deadlift with Chains', 'Kreuzheben mit Ketten', array['lower back']::text[], array['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps']::text[], 'barbell', array['You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.', 'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.', 'Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[]),
    ('Decline_Barbell_Bench_Press', 'Decline Barbell Bench Press', 'Langhantel-Negativbankdrücken', array['chest']::text[], array['shoulders', 'triceps']::text[], 'barbell', array['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'As you breathe in, come down slowly until you feel the bar on your lower chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[]),
    ('Decline_Close-Grip_Bench_To_Skull_Crusher', 'Decline Close-Grip Bench To Skull Crusher', 'Negativbank: enges Drücken zu Stirndrücken', array['triceps']::text[], array['chest', 'shoulders']::text[], 'barbell', array['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.', 'Using the triceps to push the bar back up, press it back to the starting position as you exhale.', 'As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.', 'Lift the bar back to the starting position by contracting the triceps and exhaling.', 'Repeat steps 3-6 until the recommended amount of repetitions is performed.']::text[]),
    ('Decline_Crunch', 'Decline Crunch', 'Negativbank-Crunch', array['abdominals']::text[], '{}'::text[], 'body only', array['Secure your legs at the end of the decline bench and lie down.', 'Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.', 'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.', 'After the one second contraction, begin to come down slowly again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Decline_Dumbbell_Bench_Press', 'Decline Dumbbell Bench Press', 'Kurzhantel-Negativbankdrücken', array['chest']::text[], array['shoulders', 'triceps']::text[], 'dumbbell', array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[]),
    ('Decline_Dumbbell_Flyes', 'Decline Dumbbell Flyes', 'Kurzhantel-Fliegende an der Negativbank', array['chest']::text[], '{}'::text[], 'dumbbell', array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[]),
    ('Decline_Dumbbell_Triceps_Extension', 'Decline Dumbbell Triceps Extension', 'Kurzhantel-Trizeps-Extension an der Negativbank', array['triceps']::text[], '{}'::text[], 'dumbbell', array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.', 'As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Breathe in as you perform this portion of the movement.', 'Lift the dumbbells back to the starting position by contracting the triceps and exhaling.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Decline_EZ_Bar_Triceps_Extension', 'Decline EZ Bar Triceps Extension', 'SZ-Stangen-Trizeps-Extension an der Negativbank', array['triceps']::text[], '{}'::text[], 'barbell', array['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.', 'Lift the bar back to the starting position by contracting the triceps and exhaling.', 'Repeat until the recommended amount of repetitions is performed.']::text[]),
    ('Decline_Oblique_Crunch', 'Decline Oblique Crunch', 'Schräger Crunch an der Negativbank', array['abdominals']::text[], '{}'::text[], 'body only', array['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.', 'Put one hand beside your head and the other on your thigh. This will be your starting position.', 'Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.', 'Lower your body back down slowly to the starting position as you inhale.', 'After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position.']::text[]),
    ('Decline_Push-Up', 'Decline Push-Up', 'Negativ-Liegestütz (Füße erhöht)', array['chest']::text[], array['shoulders', 'triceps']::text[], null, array['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[]),
    ('Decline_Reverse_Crunch', 'Decline Reverse Crunch', 'Reverse Crunch an der Negativbank', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position.', 'Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.', 'While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.', 'Hold the contraction for a second and move your legs back to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Decline_Smith_Press', 'Decline Smith Press', 'Negativbankdrücken an der Multipresse', array['chest']::text[], array['shoulders', 'triceps']::text[], 'machine', array['Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position.', 'As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso.', 'After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so.', 'Repeat the movement for the prescribed amount of repetitions.', 'When the set is complete, lock the bar back in the rack.']::text[]),
    ('Deficit_Deadlift', 'Deficit Deadlift', 'Defizit-Kreuzheben', array['lower back']::text[], array['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps']::text[], 'barbell', array['Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[]),
    ('Dip_Machine', 'Dip Machine', 'Dip-Maschine', array['triceps']::text[], array['chest', 'shoulders']::text[], 'machine', array['Sit securely in a dip machine, select the weight and firmly grasp the handles.', 'Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.', 'As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.', 'Now slowly let your arms come back up to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dips_-_Chest_Version', 'Dips - Chest Version', 'Dips, brustbetont', array['chest']::text[], array['shoulders', 'triceps']::text[], 'other', array['For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.', 'While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.', 'Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.', 'Repeat the movement for the prescribed amount of repetitions.']::text[]),
    ('Dips_-_Triceps_Version', 'Dips - Triceps Version', 'Dips, trizepsbetont', array['triceps']::text[], array['chest', 'shoulders']::text[], 'body only', array['To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.', 'Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.', 'Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.']::text[]),
    ('Donkey_Calf_Raises', 'Donkey Calf Raises', 'Donkey-Wadenheben', array['calves']::text[], '{}'::text[], 'other', array['For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.', 'Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Double_Kettlebell_Alternating_Hang_Clean', 'Double Kettlebell Alternating Hang Clean', 'Doppel-Kettlebell-Umsetzen aus dem Hang, wechselseitig', array['hamstrings']::text[], array['biceps', 'calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'traps']::text[], 'kettlebells', array['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean one kettlebell to your shoulder and hold on to the other kettlebell.', 'With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up.']::text[]),
    ('Double_Kettlebell_Jerk', 'Double Kettlebell Jerk', 'Doppel-Kettlebell-Stoßen', array['shoulders']::text[], array['calves', 'quadriceps', 'triceps']::text[], 'kettlebells', array['Hold a kettlebell by the handle in each hand.', 'Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum.', 'As you do so, press the kettlebells overhead to lockout by extending the arms, using your body''s momentum to move the weights.', 'Return your feet to the ground in a split fashion, with one foot forward and one foot back.', 'Keeping the weights overhead, return to a standing position, bringing your feet together. Lower the weights to perform the next repetition.']::text[]),
    ('Double_Kettlebell_Push_Press', 'Double Kettlebell Push Press', 'Doppel-Kettlebell-Push-Press', array['shoulders']::text[], array['calves', 'quadriceps', 'triceps']::text[], 'kettlebells', array['Clean two kettlebells to your shoulders.', 'Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead.', 'Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat.']::text[]),
    ('Double_Kettlebell_Snatch', 'Double Kettlebell Snatch', 'Doppel-Kettlebell-Reißen', array['shoulders']::text[], array['glutes', 'hamstrings', 'quadriceps']::text[], 'kettlebells', array['Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.', 'Swing the kettlebells between your legs forcefully and reverse the direction.', 'Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.']::text[]),
    ('Double_Kettlebell_Windmill', 'Double Kettlebell Windmill', 'Doppel-Kettlebell-Windmühle', array['abdominals']::text[], array['glutes', 'hamstrings', 'shoulders', 'triceps']::text[], 'kettlebells', array['Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.', 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.', 'Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.', 'Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position.']::text[]),
    ('Downward_Facing_Balance', 'Downward Facing Balance', 'Balance im herabschauenden Hund', array['glutes']::text[], array['abdominals', 'hamstrings']::text[], 'exercise ball', array['Lie facedown on top of an exercise ball.', 'While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees.']::text[]),
    ('Drag_Curl', 'Drag Curl', 'Drag Curl', array['biceps']::text[], array['forearms']::text[], 'barbell', array['Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.', 'As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.', 'Slowly go back to the starting position as you keep the bar in contact with the torso at all times.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dumbbell_Alternate_Bicep_Curl', 'Dumbbell Alternate Bicep Curl', 'Kurzhantel-Bizepscurl, wechselseitig', array['biceps']::text[], array['forearms']::text[], 'dumbbell', array['Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.', 'While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.']::text[]),
    ('Dumbbell_Bench_Press', 'Dumbbell Bench Press', 'Kurzhantel-Bankdrücken', array['chest']::text[], array['shoulders', 'triceps']::text[], 'dumbbell', array['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.', 'Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[]),
    ('Dumbbell_Bench_Press_with_Neutral_Grip', 'Dumbbell Bench Press with Neutral Grip', 'Kurzhantel-Bankdrücken, neutraler Griff', array['chest']::text[], array['shoulders', 'triceps']::text[], 'dumbbell', array['Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.', 'Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.', 'Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.', 'Pause, then extend the elbow and return to the starting position.']::text[]),
    ('Dumbbell_Bicep_Curl', 'Dumbbell Bicep Curl', 'Kurzhantel-Bizepscurl', array['biceps']::text[], array['forearms']::text[], 'dumbbell', array['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dumbbell_Clean', 'Dumbbell Clean', 'Kurzhantel-Umsetzen', array['hamstrings']::text[], array['calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps']::text[], 'dumbbell', array['Begin standing with a dumbbell in each hand with your feet shoulder width apart.', 'Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.', 'To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.', 'After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.', 'Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders.']::text[]),
    ('Dumbbell_Floor_Press', 'Dumbbell Floor Press', 'Kurzhantel-Bodendrücken', array['triceps']::text[], array['chest', 'shoulders']::text[], 'dumbbell', array['Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.', 'Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.', 'Pause at the bottom, and then bring the weight together at the top by extending through the elbows.']::text[]),
    ('Dumbbell_Flyes', 'Dumbbell Flyes', 'Kurzhantel-Fliegende', array['chest']::text[], '{}'::text[], 'dumbbell', array['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.', 'Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[]),
    ('Dumbbell_Incline_Row', 'Dumbbell Incline Row', 'Kurzhantelrudern an der Schrägbank', array['middle back']::text[], array['biceps', 'forearms', 'lats', 'shoulders']::text[], 'dumbbell', array['Using a neutral grip, lean into an incline bench.', 'Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.', 'Retract the shoulder blades and flex the elbows to row the dumbbells to your side.', 'Pause at the top of the motion, and then return to the starting position.']::text[]),
    ('Dumbbell_Incline_Shoulder_Raise', 'Dumbbell Incline Shoulder Raise', 'Kurzhantel-Schulterheben an der Schrägbank', array['shoulders']::text[], array['triceps']::text[], 'dumbbell', array['Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs.', 'Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position.', 'While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe out.', 'Bring back the dumbbells to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dumbbell_Lunges', 'Dumbbell Lunges', 'Kurzhantel-Ausfallschritte', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'dumbbell', array['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[]),
    ('Dumbbell_Lying_One-Arm_Rear_Lateral_Raise', 'Dumbbell Lying One-Arm Rear Lateral Raise', 'Einarmiges liegendes Reverse Fly mit Kurzhantel', array['shoulders']::text[], array['middle back']::text[], 'dumbbell', array['While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. The other hand can be used to hold to the leg of the bench for stability.', 'Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.', 'Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbell to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dumbbell_Lying_Pronation', 'Dumbbell Lying Pronation', 'Liegende Pronation mit Kurzhantel', array['forearms']::text[], '{}'::text[], 'dumbbell', array['Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', 'Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.', 'Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.', 'As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.', 'As you breathe in, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dumbbell_Lying_Rear_Lateral_Raise', 'Dumbbell Lying Rear Lateral Raise', 'Liegendes Reverse Fly mit Kurzhanteln', array['shoulders']::text[], '{}'::text[], 'dumbbell', array['While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench.', 'Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.', 'Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbells to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[]),
    ('Dumbbell_Lying_Supination', 'Dumbbell Lying Supination', 'Liegende Supination mit Kurzhantel', array['forearms']::text[], '{}'::text[], 'dumbbell', array['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', 'Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.', 'Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.', 'As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.', 'As you breathe in, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[]),
    ('Dumbbell_One-Arm_Shoulder_Press', 'Dumbbell One-Arm Shoulder Press', 'Einarmiges Kurzhantel-Schulterdrücken', array['shoulders']::text[], array['triceps']::text[], 'dumbbell', array['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.', 'Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.', 'Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.', 'As you exhale, push the dumbbell up until your arm is fully extended.', 'After a second pause, slowly come down back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions and then switch arms.']::text[]),
    ('Dumbbell_One-Arm_Triceps_Extension', 'Dumbbell One-Arm Triceps Extension', 'Einarmige Kurzhantel-Trizeps-Extension', array['triceps']::text[], '{}'::text[], 'dumbbell', array['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.', 'Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.', 'Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.', 'Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.', 'Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.', 'Repeat for the recommended amount of repetitions and switch arms.']::text[]),
    ('Dumbbell_One-Arm_Upright_Row', 'Dumbbell One-Arm Upright Row', 'Einarmiges Kurzhantel-Aufrechtrudern', array['shoulders']::text[], array['biceps', 'traps']::text[], 'dumbbell', array['Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs.', 'Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position.', 'Use your side shoulders to lift the dumbbell as you exhale. The dumbbell should be close to the body as you move it up. Continue to lift it until the dumbbell is nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the dumbbell back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions and switch arms.']::text[]),
    ('Dumbbell_Prone_Incline_Curl', 'Dumbbell Prone Incline Curl', 'Kurzhantel-Curl bäuchlings an der Schrägbank', array['biceps']::text[], '{}'::text[], 'dumbbell', array['Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way).', 'Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor.', 'Now keep your elbows in by your side and face the palms forward. This will be your starting position.', 'Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as you perform this portion of the movement and ensure that only the forearms move. The upper arms should remain stationary at all times.', 'Lower the dumbbells until your arms are fully extended.', 'Repeat for the recommended amount of times.']::text[]),
    ('Dumbbell_Raise', 'Dumbbell Raise', 'Kurzhantel-Heben', array['shoulders']::text[], array['biceps']::text[], 'dumbbell', array['Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be next to your thighs with the palm of your hands facing back.', 'Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be to the side of the body as you move them up. Continue to lift it until the dumbbells are nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dumbbell_Rear_Lunge', 'Dumbbell Rear Lunge', 'Kurzhantel-Ausfallschritt rückwärts', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'dumbbell', array['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.', 'Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.', 'Now repeat with the opposite leg.']::text[])
  ) as v(source_id, name_en, name_de, primary_muscles, secondary_muscles, equipment, instructions_en)
  on conflict (user_id, source, source_id) do update set
    name_en = excluded.name_en,
    name_de = excluded.name_de,
    primary_muscles = excluded.primary_muscles,
    secondary_muscles = excluded.secondary_muscles,
    equipment = excluded.equipment,
    instructions_en = excluded.instructions_en;
end
$seed$;
